ENFORCEMENT = re.compile(r"komorni|egzekuc|zaje(?:l|ci)|zajeci", re.I)
DIACRITICS = str.maketrans("ąćęłńóśźżĄĆĘŁŃÓŚŹŻ", "acelnoszzACELNOSZZ")


def plain(text):
    return text.translate(DIACRITICS)


def lowered(text):
    return plain(text).lower().rstrip("?.!")


def thread(first, answer, follow):
    return f"Użytkownik: {first}\n\nAsystent: {answer}\n\nUżytkownik: {follow}"


def main():
    out = []
    criminal_domain = "dr-03"

    def add(q, kind, legal, dr=None, skill=None, variant="oryginal"):
        item = {"q": q, "kind": kind, "legal": legal, "dr": dr, "variant": variant}
        if skill:
            item["skill"] = skill
        if legal:
            # Bailiff enforcement is DR-03 by the routing table, but civil (KPC): no KK qualifier.
            item["criminal"] = dr == criminal_domain and not ENFORCEMENT.search(plain(q))
        out.append(item)

    for name in ["routing-domains-500.json", "routing-domains-holdout.json"]:
        for case in json.load(open(os.path.join(HERE, name), encoding="utf-8")):
            if case["dr"] is None and not case.get("skill"):
                continue
            add(case["q"], "executive" if case.get("skill") else "legal", True, case["dr"], case.get("skill"), "fixture-" + name.split("-")[-1].split(".")[0])

    legal_variants = [
        ("oryginal", lambda q: q),
        ("bez-polskich-znakow", plain),
        ("male-litery", lowered),
        ("powitanie", lambda q: "Dzień dobry, mam pytanie. " + q),
        ("prosba", lambda q: q.rstrip("?.!") + ". Co mogę zrobić?"),
    ]
    for dr, seeds in LEGAL.items():
        for seed in seeds:
            for variant, render in legal_variants:
                add(render(seed), "legal", True, dr, None, variant)
    for seed, dr, skill in EXECUTIVE:
        for variant, render in legal_variants:
            add(render(seed), "executive", True, dr, skill, variant)
    nonlegal_variants = [
        ("oryginal", lambda q: q),
        ("bez-polskich-znakow", plain),
        ("male-litery", lowered),
        ("powitanie", lambda q: "Hej, " + q[0].lower() + q[1:]),
        ("pytanie", lambda q: "Mam pytanie: " + q[0].lower() + q[1:]),
        ("podziekowanie", lambda q: q + " Dzięki z góry."),
    ]
    for seed in NONLEGAL:
        for variant, render in nonlegal_variants:
            add(render(seed), "nonlegal", False, None, None, variant)
    for seed in TRIVIAL:
        add(seed, "trivial", False, None, None, "oryginal")
    for first, answer, follow, dr in FOLLOWUPS:
        for variant, render in legal_variants:
            add(thread(first, answer, render(follow)), "followup", True, dr, None, variant)
    for first, answer, follow in FOLLOWUP_TRIVIAL:
        add(thread(first, answer, follow), "trivial", False, None, None, "watek")

    # Fill to exactly 5000 with more diacritic-free/lowercase legal variants.
    extra = [(dr, seed) for dr, seeds in LEGAL.items() for seed in seeds]
    index = 0
    while len(out) < 5000:
        dr, seed = extra[index % len(extra)]
        add("pytanie: " + lowered(seed), "legal", True, dr, None, "pytanie-male-litery")
        index += 1
    out = out[:5000]
    with open(os.path.join(HERE, "routing-5000.json"), "w", encoding="utf-8") as handle:
        json.dump(out, handle, ensure_ascii=False, indent=0)
        handle.write("\n")
    counts = {}
    for item in out:
        counts[item["kind"]] = counts.get(item["kind"], 0) + 1
    print(len(out), counts)


if __name__ == "__main__":
    main()
